var t=`0273-idrijski-zlikrofi`;var n=`world-0273`;var o=`SI`;var l=`southern-europe`;var a=4;var r=69;var s={en:`Idrijski Žlikrofi`,ua:`Ідрійські жлікрофі`};var g={en:`A traditional Slovenia dish made with all-purpose flour, chicken egg, potato, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Словенія. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, картопля, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 24 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 24 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:24,i:[[`all-purpose-flour`,400,`g`],[`chicken-egg`,2,`pcs`],[`water`,115,`ml`],[`table-salt`,4,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:14,i:[[`potato`,460,`g`],[`yellow-onion`,110,`g`],[`smoked-ham`,130,`g`],[`unsalted-butter`,30,`g`],[`dried-marjoram`,3,`g`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:22,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 9 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 9 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:9,i:[[`water`,1500,`ml`]]}];var d={slug:t,id:n,country:`SI`,region:l,servings:4,minutes:69,title:s,text:g,steps:u};export{o as country,d as default,n as id,r as minutes,l as region,a as servings,t as slug,u as steps,g as text,s as title};